public record Money(BigDecimal amount, Currency currency) {
    public Money {
        Objects.requireNonNull(amount);
        if (amount.signum() < 0) throw new IllegalArgumentException();
    }

    public Money add(Money other) {
        if (!this.currency.equals(other.currency)) throw new IllegalArgumentException();
        return new Money(this.amount.add(other.amount), this.currency);
    }
}

public void addLineItem(ProductId pid, Money price) {
    if (this.status != DRAFT) throw new IllegalStateException();

    var item = new OrderItem(pid, price);
    if (this.total.add(item.price()).isOverLimit()) {
        throw new IllegalStateException("Limit exceeded");
    }
    this.items.add(item);
    this.total = this.total.add(item.price());
}

public void confirm() {
    this.status = CONFIRMED;
    this.events.add(new OrderConfirmedEvent(this.id));
}

public List<DomainEvent> pullEvents() {
    var copy = List.copyOf(this.events);
    this.events.clear();
    return copy;
}

